<div class="estudiantes-explorador-control" x-show="['cursos','especialidades'].includes(vista)"><button type="button" class="ui-btn ui-btn-secondary" x-on:click="explorador=!explorador" :aria-expanded="explorador"><i class="ph-duotone ph-squares-four" aria-hidden="true"></i><span x-text="vista==='cursos'?'Explorar cursos':'Explorar especialidades'"></span><i class="ph-duotone ph-caret-down" :class="{'estudiantes-caret-abierto':explorador}" aria-hidden="true"></i></button><p class="ui-muted text-xs">Abre los grupos cuando quieras navegar por ellos.</p></div>
<section x-show="vista==='cursos' && explorador" x-cloak x-transition.opacity.duration.160ms aria-label="Agrupar estudiantes por curso"><div class="estudiantes-grupos-intro"><h2 class="ui-title font-bold">Explora por curso</h2><p class="ui-muted text-xs mt-1">Abre un curso o un paralelo para consultar sus estudiantes.</p></div><div class="estudiantes-grupos-grid"><template x-for="curso in datos.cursos" :key="curso.valor"><article class="ui-card estudiantes-grupo"><button type="button" class="estudiantes-grupo-principal" :disabled="!curso.total || cargandoGrupo" x-on:click="seleccionarGrupo('seleccionarCursoCarpeta',curso.valor)"><i class="ph-duotone ph-chalkboard" aria-hidden="true"></i><span><strong x-text="curso.nombre"></strong><small>estudiantes en la selección</small></span><b x-text="curso.total"></b></button><div class="estudiantes-paralelos"><template x-for="par in curso.paralelos" :key="par.valor"><button type="button" :disabled="!par.total || cargandoGrupo" x-on:click="seleccionarGrupo('filtrarCursoParalelo',curso.valor,par.valor)" :aria-label="curso.nombre+', paralelo '+par.nombre+': '+par.total+' estudiantes'"><span x-text="par.nombre"></span><strong x-text="par.total"></strong></button></template></div></article></template></div></section>
<section x-show="vista==='especialidades' && explorador" x-cloak x-transition.opacity.duration.160ms aria-label="Agrupar estudiantes por especialidad"><div class="estudiantes-grupos-intro"><h2 class="ui-title font-bold">Explora por especialidad</h2><p class="ui-muted text-xs mt-1">La especialidad registrada acompaña el trayecto del estudiante; no se asigna a quienes todavía no tienen una.</p></div><div class="estudiantes-especialidades-grid"><template x-for="esp in datos.especialidades" :key="esp.valor"><button type="button" class="ui-card estudiantes-especialidad" :disabled="!esp.total || cargandoGrupo" x-on:click="seleccionarGrupo('seleccionarEspecialidadCarpeta',esp.valor)"><i class="ph-duotone ph-graduation-cap" aria-hidden="true"></i><strong x-text="esp.nombre"></strong><span><b x-text="esp.total"></b> estudiantes</span><i class="ph-duotone ph-arrow-up-right" aria-hidden="true"></i></button></template><button class="ui-card estudiantes-especialidad" type="button" :disabled="!datos.sin_especialidad || cargandoGrupo" x-on:click="seleccionarGrupo('set','filtroEspecialidad','SIN_ESPECIALIDAD')"><i class="ph-duotone ph-compass" aria-hidden="true"></i><strong>Sin especialidad registrada</strong><span><b x-text="datos.sin_especialidad"></b> estudiantes</span><i class="ph-duotone ph-arrow-up-right" aria-hidden="true"></i></button></div></section>
